// 1. Validar la disponibilidad del servicio
pm.test("Status code es 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Validar eficiencia y rendimiento (Criterio clave en microservicios)
pm.test("Tiempo de respuesta es óptimo (Menor a 500ms)", function () {
    pm.expect(pm.response.responseTime).to.be.below(1500);
});

// 3. Validar el formato del contrato de datos
pm.test("La respuesta contiene un JSON válido", function () {
    pm.response.to.be.json;
});
